msgs=json.loads((p/'messages.json').read_text()); byid={m['id']:m for m in msgs}
for f in sorted(p.glob('page-*.json')):
 d=json.loads(f.read_text()); print(f.name, 'envelope', {k:v for k,v in d.items() if k!='data'}); print('data keys',d['data'].keys())
 for k,v in d['data'].items():
  if k!='messages': print(k,v)
 for m in d['data'].get('messages',[]):
  base=byid.get(m.get('id'),{}); delta={k:v for k,v in m.items() if k not in base or base[k]!=v}; print('message',m.get('id'),'additional/different fields',delta)
PY"}

